function InputComponent({ setName, setAge }) {
    return (
        <div>
            <input
                type="text"
                placeholder="Name"
                onChange={(e) => setName(e.target.value)}
            />

            <input
                type="text"
                placeholder="Age"
                onChange={(e) => setAge(e.target.value)}
            />
        </div>
    );
}

export default InputComponent;
